const s=document.getElementById("csvForm"),l=document.getElementById("file"),t=document.getElementById("output");import{loadChunkedScript as i}from"/js/chunkload.js?v=8";s&&s.addEventListener("submit",async c=>{c.preventDefault();const n=l.files&&l.files[0];if(!n){t.innerHTML='<p class="hint">Сначала выберите CSV-файл.</p>';return}try{typeof XLSX>"u"&&await i("/libs/xlsx.full.min.js")}catch{t.innerHTML='<p class="hint" style="color:#c0392b">Библиотека SheetJS не загрузилась. Проверьте интернет.</p>';return}try{const e=new FileReader;e.onload=o=>{try{const r=XLSX.read(new Uint8Array(o.target.result),{type:"array"});XLSX.writeFile(r,"converted.xlsx"),t.innerHTML=`<p style="margin:0">✅ Готово! Файл <strong>converted.xlsx</strong> скачан. Листов: ${r.SheetNames.length}</p>`}catch(r){t.innerHTML=`<p class="hint" style="color:#c0392b">Не удалось прочитать файл: ${r.message}</p>`}},e.onerror=()=>{t.innerHTML='<p class="hint" style="color:#c0392b">Ошибка чтения файла.</p>'},e.readAsArrayBuffer(n)}catch(e){t.innerHTML=`<p class="hint" style="color:#c0392b">Ошибка: ${e.message}</p>`}});
